/// AAC is lossy and the reference is rendered from the original PCM, so
/// only coding-noise-level closeness is asserted.
#[test]
fn aac_stereo_decodes() {
    render_case("test_000090", 0, 0, 512);
}

/// Ambisonics PROJECTION mode: decoded substreams through the Q1.15
/// demixing matrix (near-identity, LPCM).
#[test]
fn projection_foa_to_stereo() {
    render_case("test_000042", 0, 0, 1);
}

/// PROJECTION with coupled Opus substreams. Like the AAC case, the
/// reference is rendered from the pre-codec PCM, so the tolerance covers
/// Opus coding noise (observed max 2839, ~18 dB SNR at 0.99 correlation);
/// a channel-mapping or matrix bug would far exceed it.
#[test]
fn projection_opus_coupled_to_stereo() {
    render_case("test_000048", 0, 0, 3000);
}

/// No reference WAVs exist for sound systems E–H and 9.1.6, so assert
/// shape and sanity: correct channel count, same duration as the stereo
/// render, all samples finite, output not silent.
#[test]
fn extended_sound_systems_render_sanely() {
    let data = require_vectors!(
        std::fs::read(vectors_dir().join("test_000070.iamf")).ok(),
        "test_000070"
    );
    let render = |sound_system: u8| {
        let descriptors = Descriptors::collect(&data).unwrap();
        let target = SoundSystem::from_u8(sound_system).unwrap();
        let mut decoder =
            PresentationDecoder::new(&descriptors, 0, target, &DefaultFactory).unwrap();
        for obu in ObuIter::new(&data).map(Result::unwrap) {
            decoder.process_obu(&obu).unwrap();
        }
        decoder.finish().unwrap()
    };
    let stereo = render(0);
    let frames = stereo.interleaved.len() / stereo.channels;
    // E (4+5+1), F (3+7+0), G (4+9+0), H (9+10+3), 9.1.6.
    for (sound_system, channels) in [(4u8, 11usize), (5, 12), (6, 14), (7, 24), (13, 16)] {
        let mix = render(sound_system);
        assert_eq!(mix.channels, channels, "sound system {sound_system}");
        assert_eq!(
            mix.interleaved.len(),
            frames * channels,
            "sound system {sound_system}: duration"
        );
        assert!(
            mix.interleaved.iter().all(|s| s.is_finite()),
            "sound system {sound_system}: non-finite samples"
        );
        assert!(
            mix.interleaved.iter().any(|&s| s.abs() > 1e-4),
            "sound system {sound_system}: silent output"
        );
    }
}

/// Binaural (output layout 14) currently uses the same gain matrices as
/// the stereo render — libiamf-without-binauralizer behavior — so the two
/// must match exactly.
#[test]
fn binaural_matches_stereo_fallback() {
    let dir = vectors_dir();
    for vector in ["test_000070", "test_000038", "test_000086"] {
        let data = require_vectors!(
            std::fs::read(dir.join(format!("{vector}.iamf"))).ok(),
            format_args!("{vector}")
        );
        let render = |sound_system: u8| {
            let descriptors = Descriptors::collect(&data).unwrap();
            let target = SoundSystem::from_u8(sound_system).unwrap();
            let mut decoder =
                PresentationDecoder::new(&descriptors, 0, target, &DefaultFactory).unwrap();
            for obu in ObuIter::new(&data).map(Result::unwrap) {
                decoder.process_obu(&obu).unwrap();
            }
            decoder.finish().unwrap().interleaved
        };
        assert_eq!(render(14), render(0), "{vector}: binaural != stereo");
    }
}
